module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] window [0:20];
  integer i, j, k;
  reg [7:0] t;
  reg [7:0] temp_array [0:20];
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) window[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      window[0] <= x;
      for (i = 1; i < 21; i = i + 1) window[i] <= temp_array[i];
      for (j = 0; j < 20; j = j + 1)
        for (k = j + 1; k < 21; k = k + 1)
          if (window[j] > window[k]) begin t = window[j]; window[j] = window[k]; window[k] = t; end
      y <= {8'd0, window[10]};
    end
    temp_array[0] <= x;
    for (i = 1; i < 21; i = i + 1) temp_array[i] <= window[i-1];
  end
endmodule

